use opensource::{assets::Assets,scene::Scene};
#[test] fn authored_draw_fire_and_idle(){let fs=Assets::from_game("../portal-original/portal",None).unwrap();let mut s=Scene::weapon_viewmodel(&fs,"weapon_portalgun").unwrap();assert!(s.vertices.iter().all(|v|v.unlit==2.)); assert!(s.textures.iter().all(|t|t.chunks_exact(4).any(|p|p[3]>0)),"original hands must not be hidden");s.pose_weapon("draw",0.).unwrap();let a=s.vertices.iter().map(|v|v.position).collect::<Vec<_>>();s.pose_weapon("draw",0.5).unwrap();assert!(s.vertices.iter().zip(a).any(|(b,a)|glam::Vec3::from(b.position).distance(a.into())>0.01));s.pose_weapon("fire1",0.).unwrap();let a=s.vertices.iter().map(|v|v.position).collect::<Vec<_>>();s.pose_weapon("fire1",0.2).unwrap();assert!(s.vertices.iter().zip(a).any(|(b,a)|glam::Vec3::from(b.position).distance(a.into())>0.01));assert_eq!(s.weapon_pose("fire1",0.6).unwrap(),("idle".into(),0.));}
#[test] fn variant_spawn_names_are_loadouts(){let fs=Assets::from_game("../portal-original/portal",None).unwrap();for (map,want) in [("testchmb_a_06",[true,false]),("testchmb_a_07",[true,false]),("testchmb_a_08",[true,true]),("testchmb_a_10",[true,true])]{let b=fs.read(&format!("maps/{map}.bsp")).unwrap();let mut r=opensource::entity::Runtime::new(&b).unwrap();r.direct_launch_loadout();assert_eq!(r.portal_inventory,want,"{map}");}}
